// The package's public facade. Every export it advertises is re-exported
// from the sibling `lib.js` INSIDE THIS SAME installed package (RWF-004a).
//
// What makes this fixture RWF-025b's is the bookkeeping in the middle: a
// telemetry table keyed by the exported functions themselves. Those
// statements only READ the aliases -- they are computed keys and element
// indices -- but the reassignment collector used to walk every child of an
// assignment target and record every identifier under it, so `vulnerable`
// landed in the file's `reassignedNames`. That set is file-wide and
// authoritative-negative, so this one unrelated statement withdrew the
// `./lib` re-export origin for an export it has nothing to do with.

var vulnerable = require("./lib").vulnerable;
var safe = require("./lib").safe;
var unused = require("./lib").unused;
var rebound = require("./lib").reboundOriginal;

var REGISTRY = {};
var seen;

function keyFor(fn) {
  return typeof fn === "function" ? fn.name : String(fn);
}

// (1) A computed KEY that merely reads `vulnerable`. Rebinds `seen`.
({ [keyFor(vulnerable)]: seen } = REGISTRY);

// (2) An element-access INDEX that merely reads `vulnerable`. Rebinds
//     nothing at all -- it mutates REGISTRY.
REGISTRY[keyFor(vulnerable)] = true;

// (3) `safe` is deliberately left out of the bookkeeping above, so its
//     attribution is identical before and after RWF-025b. It is the
//     control that shows the two statements, and not the re-export shape,
//     are what differed.

// (4) A GENUINE reassignment, written inside an evaluated position so that
//     it is exactly the shape RWF-025b must still detect. `rebound` is no
//     longer `reboundOriginal` after this line, and attribution for it
//     must stay refused.
REGISTRY[(rebound = require("./lib").reboundReplacement)] = true;

exports.vulnerable = vulnerable;
exports.safe = safe;
exports.unused = unused;
exports.rebound = rebound;
